class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_root = False  # Marks end of root word

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        curr = self.root
        for char in word:
            if char not in curr.children:
                curr.children[char] = TrieNode()
            curr = curr.children[char]
        curr.is_root = True  # Mark the end of a root word

    def get_shortest_root(self, word):
        curr = self.root
        prefix = ""
        for char in word:
            if char not in curr.children:
                return None
            curr = curr.children[char]
            prefix += char
            if curr.is_root:
                return prefix  # Return as soon as a root is found (guaranteed shortest)
        return None

def replaceWords(dictionary, sentence):
    trie = Trie()
    # Insert all roots into the Trie
    for root in dictionary:
        trie.insert(root)

    res = []
    # Process each word in the sentence
    for word in sentence.split():
        root = trie.get_shortest_root(word)
        if root:
            res.append(root)
        else:
            res.append(word)
    return " ".join(res)
